//! Generated by `scripts/gen_benches.py`: times `lean_runtime::semantics::sint::isize_to_int`; the
//! native twin is `benches/native/Bench/IsizeToInt.lean`.
//! operands in the int32 range, so the Int is a scalar word on both sides

#![allow(unused_parens, unused_imports, unused_variables, unused_mut)]
#![allow(
    clippy::double_parens,
    clippy::unnecessary_cast,
    clippy::redundant_closure
)]
#![allow(clippy::identity_op, clippy::let_and_return)]

use lean_runtime::semantics::sint;
use lean_runtime_bench::*;
use std::hint::black_box;

#[inline(never)]
fn kernel(inp: &(), n: u64) -> u64 {
    let (mut x, mut acc) = (SEED, 0u64);
    for _ in 0..n {
        x = step(x);
        acc = mix(
            acc,
            int_unbox(int_box(sint::isize_to_int(
                (((x >> 32) as u32 as i32 as i64) as u64) as usize,
            ))) as u64,
        );
    }
    acc
}

fn main() {
    run(|| (), kernel)
}
